@startuml

class OilWell {
  + code : string
  + pollutionRate() : float
}

abstract class OnshoreWell {}

abstract class OffshoreWell {
  + installationYear : date
}

class OnshoreWell {
  + surfaceExtension : float
}

class OffshoreWell {
  + geographicalAreaCode : string
}

class OilCompany {
  + taxCode : string
  + numberOfEmployees : int
}

class GeographicalArea {
  + code : string
  + environmentalImportance : int
}

class ExtractionInfo {
  + quantity : float
}

OilWell "1" o-- "0..*" ExtractionInfo
OilCompany "1" o-- "0..*" ExtractionInfo
ExtractionInfo -- OilWell
ExtractionInfo -- OilCompany

OnshoreWell --|> OilWell
OffshoreWell --|> OilWell

OffshoreWell "0..1" o-- "0..1" GeographicalArea

@enduml

